"use strict";function openMacrosModal(i){var t=openModal(modalShell({icon:"fa-solid fa-bolt",kicker:"Redactor \xB7 macros",titleChip:i.ticket_number,title:"Macros y atajos",width:"lg",body:'<div class="tkt-field"><input type="search" class="tkt-input" id="tkt-macro-search" placeholder="Buscar macro\u2026" aria-label="Buscar macro"></div><div id="tkt-macro-list"><div class="tkt-empty-box">Cargando\u2026</div></div>',foot:'<button type="button" class="tkt-btn tkt-btn-primary" id="tkt-macro-apply" disabled>Aplicar macro</button><a href="'+TKA.urls.macrosIndex+'" class="tkt-btn tkt-link-plain">Editar macros</a><button type="button" class="tkt-btn" data-modal-close>Cancelar</button>'}));loadMacros(function(a){if(!a.length){t.find("#tkt-macro-list").html('<div class="tkt-empty-box">No hay macros disponibles todav\xEDa.</div>');return}t.find("#tkt-macro-list").html(a.map(function(o){var n=(o.effects||[]).map(function(c){return"<li>"+escapeHtml(c)+"</li>"}).join("");return'<label class="tkt-option tkt-macro-row" data-macro-name="'+escapeHtml((o.name||"").toLowerCase())+'"><input type="radio" name="tkt-macro-pick" value="'+o.id+'"><span class="tkt-option-body"><span class="tkt-option-title">'+escapeHtml(o.name)+"</span>"+(o.description?'<span class="tkt-option-sub">'+escapeHtml(o.description)+"</span>":"")+(n?'<ul class="tkt-macro-effects">'+n+"</ul>":"")+"</span></label>"}).join(""))}),t.on("change",'[name="tkt-macro-pick"]',function(){t.find(".tkt-option").removeClass("on"),$(this).closest(".tkt-option").addClass("on"),t.find("#tkt-macro-apply").prop("disabled",!1)}),t.on("input","#tkt-macro-search",function(){var a=this.value.trim().toLowerCase();t.find(".tkt-macro-row").each(function(){$(this).toggle(!a||String($(this).data("macro-name")).indexOf(a)>-1)})}),t.on("click","#tkt-macro-apply",function(){var a=t.find('[name="tkt-macro-pick"]:checked').val();a&&(closeModal(),applyMacro(i,a))})}
